from typing import List


def decimal_digits(n: int) -> List[int]:
    if n == 0:
        return []
    out: List[int] = []
    while n > 0:
        out.append(n % 10)
        n //= 10
    return out


def digit_power_sum(n: int) -> int:
    ds = decimal_digits(n)
    L = len(ds)
    return sum(d ** L for d in ds)


def is_narcissistic(n: int) -> bool:
    return n == digit_power_sum(n)


def main() -> None:
    print("Theorem 1: digit-power sum <= d * 9**d (worst case all-nines)")
    for d in range(1, 13):
        worst = int("9" * d)
        assert digit_power_sum(worst) == d * 9 ** d
        print(f"  d={d:2d}: max sum = {d * 9 ** d}")
    crossover = next(d for d in range(1, 200) if d * 9 ** d < 10 ** (d - 1))
    print(f"Theorem 2: exact crossover d = {crossover} (so the d>=61 statement is sharp)")
    champ = 115132219018763992565095597973971522401
    print(f"Theorem 3: record {champ} ({len(str(champ))} digits)")
    print(f"  narcissistic? {is_narcissistic(champ)}; < 10**60? {champ < 10 ** 60}")


if __name__ == "__main__":
    main()

