function NARCISSISTIC_WITH_D_DIGITS(d):
    results <- []
    lo <- 10^(d-1); hi <- 10^d
    for each multiset M of size d over {0,...,9}:   # C(d+9, 9) of them
        v <- sum(c^d for c in M)
        if lo <= v < hi:
            if sorted(digits(v)) == sorted(M):
                results.append(v)
    return sort(results)
